}

/* ============================================================
   SECCIÓN D — Utilidad .container
   ============================================================ */

.container {
  width: 100%;
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--container-padding);
}

/* ============================================================
   SECCIÓN E — Navegación (#main-nav, .nav, .nav__*)
   ============================================================ */

#main-nav,
.nav {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: var(--nav-height);
  z-index: var(--z-nav);
  background: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
  box-shadow: var(--shadow-sm);
}

.nav .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
}

.nav__logo {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-bold);
  color: var(--color-primary);
  letter-spacing: -0.01em;
}

/* Botón hamburguesa */
.nav__toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: var(--border-radius-sm);
  color: var(--color-text);
  transition: background-color var(--transition-fast);
}

.nav__toggle:hover {
  background-color: var(--color-bg-alt);
}

/* Lista de navegación — móvil primero */
/* FIX #4 y #7: Estado inicial oculto en móvil. Sin .is-visible el menú
   está fuera de pantalla e invisible. Se usa clip + visibility para
   mantener el elemento en el DOM sin ocupar espacio visual ni ser
   interactuable, permitiendo la transición de entrada. */
.nav__list {
  display: flex;
  position: fixed;
  top: var(--nav-height);
  left: 0;
  width: 100%;
  background: var(--color-bg);
  flex-direction: column;
  padding: var(--space-4);
  gap: var(--space-2);
  border-top: 1px solid var(--color-border);
  box-shadow: var(--shadow-md);
  z-index: var(--z-overlay);

  /* Estado inicial oculto en móvil */
  opacity: 0;
  visibility: hidden;
  transform: translateY(-0.5rem);
  transition:
    opacity var(--transition-base),
    visibility var(--transition-base),
    transform var(--transition-base);
  pointer-events: none;
}

/* FIX #4 y #7: El menú solo es visible cuando tiene .is-visible */
.nav__list.is-visible {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  pointer-events: auto;
}

.nav__item {
  width: 100%;
}

.nav__link {
  display: block;
  padding: var(--space-2) var(--space-3);
  border-radius: var(--border-radius-sm);
  font-weight: var(--font-weight-medium);
  color: var(--color-text);
  transition: color var(--transition-fast), background-color var(--transition-fast);
}

.nav__link:hover {
  color: var(--color-primary);
  background-color: var(--color-bg-alt);
}

.nav__link.is-active {
  color: var(--color-primary);
  background-color: var(--color-bg-alt);
  font-weight: var(--font-weight-bold);
}

/* Desktop: >= 48em */
@media (min-width: 48em) {
  .nav__toggle {
    display: none;
  }

  /* FIX: En desktop el menú siempre es visible, se restablecen
     todos los valores de ocultamiento móvil. No se usa !important
     en display porque en desktop el menú no necesita el mecanismo
     de .is-visible — siempre está visible. */
  .nav__list {
    position: static;
    flex-direction: row;
    width: auto;
    background: transparent;
    padding: 0;
    gap: var(--space-1);
    border-top: none;
    box-shadow: none;
    z-index: auto;

    /* Restablecer estado de visibilidad para desktop */
    opacity: 1;
    visibility: visible;
    transform: none;
    pointer-events: auto;
  }

  .nav__item {
    width: auto;
  }
}

/* ============================================================
   SECCIÓN F — Layout de secciones (.section, main padding)
   ============================================================ */

/* Compensar el nav fijo */
main {
  padding-top: var(--nav-height);
}

.section {
  padding-block: var(--space-16);
}

.section:nth-child(even) {
  background-color: var(--color-bg-alt);
}

.section__header {
  text-align: center;
  margin-bottom: var(--space-12);
}

.section__header h2 {
  color: var(--color-text);
  margin-bottom: var(--space-4);
}

.section__header p {
  font-size: var(--font-size-lg);
  color: var(--color-text-muted);
  max-width: 40rem;
  margin-inline: auto;
}

.section__body {
  /* contenedor genérico del cuerpo de sección */
}

/* ============================================================
   SECCIÓN G — Grid (.grid, .grid--2col, .grid--3col)
   ============================================================ */

.grid {
  display: grid;
  gap: var(--space-8);
}

.grid--2col {
  grid-template-columns: 1fr;
}

.grid--3col {
  grid-template-columns: 1fr;
}

@media (min-width: 40em) {
  .grid--2col {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 48em) {
  .grid--3col {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* ============================================================
   SECCIÓN H — Hero (.hero, .hero__*)
   ============================================================ */

.hero {
  min-height: calc(100vh - var(--nav-height));
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(
    135deg,
    var(--color-bg) 0%,
    var(--color-bg-alt) 100%
  );
  text-align: center;
  padding-block: var(--space-24);
}

.hero__content {
  max-width: 50rem;
  margin-inline: auto;
}

.hero__title {
  color: var(--color-text);
  margin-bottom: var(--space-6);
}

.hero__title span {
  color: var(--color-primary);
}

.hero__subtitle {
  font-size: var(--font-size-lg);
  color: var(--color-text-muted);
  margin-bottom: var(--space-8);
  max-width: 36rem;
  margin-inline: auto;
}

.hero__cta {
  display: flex;
  gap: var(--space-4);
  justify-content: center;
  flex-wrap: wrap;
}

/* ============================================================
   SECCIÓN I — Botones (.btn, .btn--primary, .btn--secondary, .btn--ghost)
   ============================================================ */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-6);
  border-radius: var(--border-radius-md);
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-medium);
  transition:
    background-color var(--transition-fast),
    color var(--transition-fast),
    border-color var(--transition-fast),
    box-shadow var(--transition-fast);
  white-space: nowrap;
}

.btn--primary {
  background-color: var(--color-primary);
  color: var(--color-bg);
}

.btn--primary:hover {
  background-color: var(--color-primary-dark);
  box-shadow: var(--shadow-md);
}

.btn--secondary {
  background-color: var(--color-bg-alt);
  color: var(--color-text);
  border: 1px solid var(--color-border);
}

.btn--secondary:hover {
  background-color: var(--color-border);
}

.btn--ghost {
  background-color: transparent;
  color: var(--color-primary);
  border: 1px solid var(--color-primary);
}

.btn--ghost:hover {
  background-color: var(--color-primary);
  color: var(--color-bg);
}

/* ============================================================
   SECCIÓN J — Cards (.card, .card__*)
   ============================================================ */

.card {
  display: flex;
  flex-direction: column;
  background: var(--color-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition-base), transform var(--transition-base);
}

.card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-0.25rem);
}

.card__image {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}

.card__body {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: var(--space-6);
  gap: var(--space-3);
}

.card__title {
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-bold);
  color: var(--color-text);
}

.card__excerpt {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
  line-height: var(--line-height-base);
  flex: 1;
}

.card__meta {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
  display: flex;
  gap: var(--space-3);
  flex-wrap: wrap;
}

.card__link {
  align-self: flex-start;
  margin-top: var(--space-2);
}

/* ============================================================
   SECCIÓN K — FAQ (.faq, .faq__item, .faq__question, .faq__answer)
   ============================================================ */

.faq {
  max-width: 48rem;
  margin-inline: auto;
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.faq__item {
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-md);
  overflow: hidden;
  background: var(--color-bg);
  transition: box-shadow var(--transition-fast);
}

.faq__item:hover {
  box-shadow: var(--shadow-sm);
}

.faq__question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-4) var(--space-6);
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-medium);
  color: var(--color-text);
  text-align: left;
  transition: background-color var(--transition-fast), color var(--transition-fast);
  gap: var(--space-4);
}

.faq__question:hover {
  background-color: var(--color-bg-alt);
  color: var(--color-primary);
}

/* Icono chevron via pseudo-elemento */
.faq__question::after {
  content: '';
  display: inline-block;
  width: 0.625rem;
  height: 0.625rem;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: rotate(45deg);
  flex-shrink: 0;
  transition: transform var(--transition-base);
}

.faq__item.is-open .faq__question {
  color: var(--color-primary);
  background-color: var(--color-bg-alt);
}

.faq__item.is-open .faq__question::after {
  transform: rotate(-135deg);
}

.faq__answer {
  padding: 0 var(--space-6);
  max-height: 0;
  overflow: hidden;
  transition: max-height var(--transition-slow), padding var(--transition-base);
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
  line-height: var(--line-height-base);
}

.faq__item.is-open .faq__answer {
  max-height: 30rem;
  padding-block: var(--space-4);
}

/* ============================================================
   SECCIÓN L — Cookie Banner (.cookie-banner, .cookie-banner__*)
   ============================================================ */

/* FIX #1 y #3: El banner usa exclusivamente .is-visible para mostrarse.
   El atributo hidden NO se usa en este componente. Estado inicial oculto
   via opacity/transform para permitir la transición de entrada. */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  width: 100%;
  z-index: var(--z-cookie);
  background: var(--color-text);
  color: var(--color-bg);
  padding: var(--space-4) var(--space-6);
  box-shadow: var(--shadow-lg);

  /* Estado inicial: oculto con transición */
  opacity: 0;
  transform: translateY(100%);
  transition:
    opacity var(--transition-base),
    transform var(--transition-base);
  pointer-events: none;
}

.cookie-banner.is-visible {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

.cookie-banner .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-6);
  flex-wrap: wrap;
}

.cookie-banner__text {
  font-size: var(--font-size-sm);
  line-height: var(--line-height-base);
  flex: 1;
  min-width: 15rem;
}

.cookie-banner__text a {
  color: var(--color-accent);
  text-decoration: underline;
}

.cookie-banner__actions {
  display: flex;
  gap: var(--space-3);
  flex-shrink: 0;
  flex-wrap: wrap;
}

/* Ajuste de botones dentro del banner oscuro */
.cookie-banner .btn--primary {
  background-color: var(--color-accent);
  color: var(--color-text);
}

.cookie-banner .btn--primary:hover {
  background-color: #D97706;
}

.cookie-banner .btn--secondary {
  background-color: transparent;
  color: var(--color-bg);
  border-color: rgba(255, 255, 255, 0.4);
}

.cookie-banner .btn--secondary:hover {
  background-color: rgba(255, 255, 255, 0.1);
}

/* ============================================================
   SECCIÓN M — Botón Back to Top (#back-to-top)
   ============================================================ */

/* FIX #2 y #3: El botón usa exclusivamente .is-visible para mostrarse.
   El atributo hidden NO se usa en este componente. Estado inicial oculto
   via opacity/transform para permitir la transición de entrada. */
#back-to-top {
  position: fixed;
  bottom: var(--space-8);
  right: var(--space-6);
  z-index: var(--z-top);
  width: 3rem;
  height: 3rem;
  border-radius: 50%;
  background-color: var(--color-primary);
  color: var(--color-bg);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-md);
  font-size: var(--font-size-lg);
  opacity: 0;
  transform: translateY(1rem);
  transition:
    opacity var(--transition-base),
    transform var(--transition-base),
    background-color var(--transition-fast);
  pointer-events: none;
}

#back-to-top.is-visible {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

#back-to-top:hover {
  background-color: var(--color-primary-dark);
  box-shadow: var(--shadow-lg);
}

/* ============================================================
   SECCIÓN N — Footer (.footer, .footer__copy)
   ============================================================ */

.footer {
  background-color: var(--color-text);
  color: var(--color-bg);
  padding-block: var(--space-8);
  text-align: center;
}

.footer__copy {
  font-size: var(--font-size-sm);
  color: rgba(255, 255, 255, 0.6);
}

/* ============================================================
   SECCIÓN O — Accesibilidad y utilidades
   ============================================================ */

/* Skip link para teclado */
.skip-link {
  position: absolute;
  top: -100%;
  left: var(--space-4);
  z-index: calc(var(--z-top) + 1);
  background: var(--color-primary);
  color: var(--color-bg);
  padding: var(--space-2) var(--space-4);
  border-radius: var(--border-radius-sm);
  font-weight: var(--font-weight-medium);
  transition: top var(--transition-fast);
}

.skip-link:focus {
  top: var(--space-2);
}

/* Focus visible global */
:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
}

/* Texto solo para lectores de pantalla */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ============================================================
   SECCIÓN P — Responsive ajustes finales
   ============================================================ */

@media (max-width: 47.9375em) {
  h1 {
    font-size: var(--font-size-2xl);
  }

  h2 {
    font-size: var(--font-size-xl);
  }

  .hero {
    padding-block: var(--space-16);
  }

  .section {
    padding-block: var(--space-12);
  }

  .cookie-banner .container {
    flex-direction: column;
    align-items: flex-start;
  }

  #back-to-top {
    bottom: var(--space-6);
    right: var(--space-4);
  }
}

@media (min-width: 48em) {
  :root {
    --container-padding: var(--space-8);
  }
}

@media (min-width: 64em) {
  :root {
    --container-padding: var(--space-12);
  }
}
